import {useEffect,useState} from "react";
export type Snapshot<T>={key:string;data:T};export type AsyncState<T>={status:"loading";key:string;previous?:Snapshot<T>}|{status:"success";key:string;data:T;refreshing:boolean;refreshError:string|null}|{status:"error";key:string;message:string;previous?:Snapshot<T>};export function snapshot<T>(state:AsyncState<T>):Snapshot<T>|undefined{return state.status==="success"?{key:state.key,data:state.data}:state.previous;}export function begin<T>(state:AsyncState<T>,key:string):AsyncState<T>{if(state.status==="success"&&state.key===key)return {...state,refreshing:true,refreshError:null};const previous=snapshot(state);return {status:"loading",key,previous};}export function complete<T>(state:AsyncState<T>,key:string,data:T):AsyncState<T>{return state.key!==key?state:{status:"success",key,data,refreshing:false,refreshError:null};}export function fail<T>(state:AsyncState<T>,key:string,message:string):AsyncState<T>{if(state.key!==key)return state;if(state.status==="success")return {...state,refreshing:false,refreshError:message};return {status:"error",key,message,previous:state.previous};}export function currentView<T>(state:AsyncState<T>,key:string):AsyncState<T>{return state.key===key?state:begin(state,key);}export function emptyReason(total:number,filtersActive:boolean):"out-of-range"|"filtered"|"collection"{return total>0?"out-of-range":filtersActive?"filtered":"collection";}
export function useAsyncResource<T>(key:string,load:(signal:AbortSignal)=>Promise<T>){const [state,setState]=useState<AsyncState<T>>({status:"loading",key});const [attempt,setAttempt]=useState(0);useEffect(()=>{let active=true;const controller=new AbortController();setState(previous=>begin(previous,key));async function run(){try{const data=await load(controller.signal);if(active)setState(previous=>complete(previous,key,data));}catch(error){if(!active||controller.signal.aborted)return;const message=error instanceof Error?error.message:"Nie udało się pobrać danych";setState(previous=>fail(previous,key,message));}}void run();return ()=>{active=false;controller.abort();};},[key,load,attempt]);return {state:currentView(state,key),retry:()=>setAttempt(value=>value+1)};}

